import React, { useState, useEffect, useRef, useCallback } from 'react';
import {
  Bell,
  AlertTriangle,
  Clock,
  BarChart3,
  TrendingUp,
  CheckCheck,
  Trash2,
  X
} from 'lucide-react';
import { posApi } from '../services/api';

interface Alert {
  id: string;
  type: string;
  severity: string;
  title: string;
  message: string;
  isRead: boolean;
  isDismissed: boolean;
  createdAt: string;
}

const alertIconMap: Record<string, React.ElementType> = {
  low_stock: AlertTriangle,
  shift_reminder: Clock,
  daily_summary: BarChart3,
  unusual_sales: TrendingUp,
};

const severityClasses: Record<string, string> = {
  critical: 'text-red-400 bg-red-950 border-red-800',
  warning: 'text-amber-400 bg-amber-950 border-amber-800',
  info: 'text-teal-400 bg-teal-950 border-teal-800',
};

const severityDot: Record<string, string> = {
  critical: 'bg-red-400',
  warning: 'bg-amber-400',
  info: 'bg-teal-400',
};

function timeAgo(dateStr: string): string {
  const diff = Date.now() - new Date(dateStr).getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return 'just now';
  if (mins < 60) return `${mins}m ago`;
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return `${hrs}h ago`;
  const days = Math.floor(hrs / 24);
  return `${days}d ago`;
}

export const AlertsBell: React.FC = () => {
  const [alerts, setAlerts] = useState<Alert[]>([]);
  const [open, setOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  const fetchAlerts = useCallback(async () => {
    try {
      const data = await posApi.getAlerts();
      setAlerts(Array.isArray(data) ? data : []);
    } catch {
      // silently ignore
    }
  }, []);

  const generateAndFetch = useCallback(async () => {
    setLoading(true);
    try {
      await posApi.generateAlerts();
      await fetchAlerts();
    } catch {
      await fetchAlerts();
    } finally {
      setLoading(false);
    }
  }, [fetchAlerts]);

  useEffect(() => {
    generateAndFetch();
    const interval = setInterval(fetchAlerts, 30000);
    return () => clearInterval(interval);
  }, [generateAndFetch, fetchAlerts]);

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) {
        setOpen(false);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  const unreadCount = alerts.filter((a) => !a.isRead && !a.isDismissed).length;
  const visibleAlerts = alerts.filter((a) => !a.isDismissed).slice(0, 20);

  const handleMarkRead = async (id: string) => {
    try {
      await posApi.markAlertRead(id);
      setAlerts((prev) =>
        prev.map((a) => (a.id === id ? { ...a, isRead: true } : a))
      );
    } catch {}
  };

  const handleDismiss = async (id: string) => {
    try {
      await posApi.dismissAlert(id);
      setAlerts((prev) =>
        prev.map((a) => (a.id === id ? { ...a, isDismissed: true } : a))
      );
    } catch {}
  };

  const handleMarkAllRead = async () => {
    try {
      const unread = alerts.filter((a) => !a.isRead && !a.isDismissed);
      await Promise.all(unread.map((a) => posApi.markAlertRead(a.id)));
      setAlerts((prev) =>
        prev.map((a) => (!a.isDismissed ? { ...a, isRead: true } : a))
      );
    } catch {}
  };

  const handleDismissAll = async () => {
    try {
      await posApi.dismissAllAlerts();
      setAlerts((prev) =>
        prev.map((a) => (!a.isDismissed ? { ...a, isDismissed: true } : a))
      );
    } catch {}
  };

  return (
    <div className="relative" ref={ref}>
      <button
        onClick={() => setOpen(!open)}
        className="relative h-9 w-9 inline-flex items-center justify-center rounded-xl text-slate-600 hover:bg-slate-100 hover:text-slate-900 transition cursor-pointer focus:outline-none focus-visible:ring-2 focus-visible:ring-teal-500"
        title="Smart Alerts"
      >
        <Bell className="w-5 h-5" />
        {unreadCount > 0 && (
          <span className="absolute -top-0.5 -right-0.5 min-w-[18px] h-[18px] px-1 flex items-center justify-center rounded-full bg-rose-600 text-white text-[10px] font-bold ring-2 ring-white">
            {unreadCount > 99 ? '99+' : unreadCount}
          </span>
        )}
      </button>

      {open && (
        <div className="absolute right-0 mt-2 w-80 max-h-[70vh] bg-white border border-slate-200 rounded-2xl shadow-2xl z-50 flex flex-col overflow-hidden">
          <div className="flex items-center justify-between px-4 py-3 border-b border-slate-100">
            <div className="flex items-center gap-2">
              <Bell className="w-4 h-4 text-teal-500" />
              <span className="text-sm font-bold text-slate-900">Smart Alerts</span>
              {unreadCount > 0 && (
                <span className="text-[9px] font-bold px-1.5 py-0.5 rounded-full bg-teal-500 text-white">
                  {unreadCount}
                </span>
              )}
            </div>
            <button
              onClick={() => setOpen(false)}
              className="p-1 rounded-lg text-slate-400 hover:text-slate-600 transition cursor-pointer"
            >
              <X className="w-3.5 h-3.5" />
            </button>
          </div>

          {visibleAlerts.length > 0 && (
            <div className="flex items-center gap-2 px-4 py-2 border-b border-slate-100">
              <button
                onClick={handleMarkAllRead}
                className="flex items-center gap-1 px-2 py-1 rounded-lg text-[10px] font-semibold text-teal-600 hover:bg-teal-50 transition cursor-pointer"
              >
                <CheckCheck className="w-3 h-3" />
                Mark all read
              </button>
              <button
                onClick={handleDismissAll}
                className="flex items-center gap-1 px-2 py-1 rounded-lg text-[10px] font-semibold text-slate-500 hover:bg-slate-100 transition cursor-pointer"
              >
                <Trash2 className="w-3 h-3" />
                Dismiss all
              </button>
            </div>
          )}

          <div className="flex-1 overflow-y-auto">
            {loading && visibleAlerts.length === 0 ? (
              <div className="flex items-center justify-center py-12 text-slate-500 text-xs">
                <div className="w-4 h-4 border-2 border-teal-500 border-t-transparent rounded-full animate-spin mr-2" />
                Loading alerts...
              </div>
            ) : visibleAlerts.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-12 text-slate-500">
                <Bell className="w-8 h-8 mb-2 opacity-30" />
                <span className="text-xs font-medium">No alerts</span>
                <span className="text-[10px] mt-0.5">All caught up!</span>
              </div>
            ) : (
              <div className="divide-y divide-slate-100">
                {visibleAlerts.map((alert) => {
                  const Icon = alertIconMap[alert.type] || Bell;
                  const sevClass = severityClasses[alert.severity] || severityClasses.info;
                  const dotClass = severityDot[alert.severity] || severityDot.info;
                  return (
                    <div
                      key={alert.id}
                      className={`px-4 py-3 hover:bg-slate-50 transition cursor-pointer ${
                        !alert.isRead ? 'bg-teal-50/50' : ''
                      }`}
                      onClick={() => !alert.isRead && handleMarkRead(alert.id)}
                    >
                      <div className="flex items-start gap-2.5">
                        <div className={`mt-0.5 p-1.5 rounded-lg border ${sevClass}`}>
                          <Icon className="w-3 h-3" />
                        </div>
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-1.5">
                            <span className={`text-xs font-bold ${!alert.isRead ? 'text-slate-900' : 'text-slate-600'}`}>
                              {alert.title}
                            </span>
                            {!alert.isRead && (
                              <span className={`w-1.5 h-1.5 rounded-full ${dotClass} shrink-0`} />
                            )}
                          </div>
                          <p className="text-[11px] text-slate-400 mt-0.5 line-clamp-2">
                            {alert.message}
                          </p>
                          <span className="text-[9px] text-slate-600 mt-1 block">
                            {timeAgo(alert.createdAt)}
                          </span>
                        </div>
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            handleDismiss(alert.id);
                          }}
                          className="p-1 rounded text-slate-400 hover:text-slate-600 transition cursor-pointer shrink-0"
                          title="Dismiss"
                        >
                          <X className="w-3 h-3" />
                        </button>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { PhoneCall, Search, MapPin, User, Check, X, ArrowRight } from 'lucide-react';
import { posApi } from '../services/api';

import { usePosStore } from '../store/posStore';

interface CallOrderModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export const CallOrderModal: React.FC<CallOrderModalProps> = ({ isOpen, onClose }) => {
  const { setOrderType, setCustomerInfo, selectedBranch } = usePosStore();
  const [phone, setPhone] = useState('');
  const [customerName, setCustomerName] = useState('');
  const [address, setAddress] = useState('');
  const [lookupResult, setLookupResult] = useState<any>(null);
  const [isSearching, setIsSearching] = useState(false);

  if (!isOpen) return null;

  const handleLookup = async () => {
    if (!phone.trim()) return;
    setIsSearching(true);
    try {
      const res = await posApi.lookupCustomerPhone(phone.trim());
      setLookupResult(res);
      if (res.found) {
        if (res.name) setCustomerName(res.name);
        if (res.lastAddress) setAddress(res.lastAddress);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setIsSearching(false);
    }
  };

  const handleStartOrder = () => {
    setOrderType('CallOrder');
    setCustomerInfo({
      name: customerName || 'Phone Customer',
      phone: phone || '0300-0000000',
      address: address || 'Islamabad'
    });
    onClose();
  };

  return (
    <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-slate-900 border border-slate-700 rounded-2xl max-w-lg w-full overflow-hidden shadow-2xl">
        <div className="px-5 py-4 bg-slate-800/80 border-b border-slate-700 flex items-center justify-between">
          <div className="flex items-center gap-2 text-amber-400 font-bold text-base">
            <PhoneCall className="w-5 h-5 animate-pulse" />
            <span>Phone Call Order Intake (UAN / Inbound)</span>
          </div>
          <button onClick={onClose} className="p-1 rounded-lg text-slate-400 hover:text-white hover:bg-slate-700">
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="p-5 space-y-4">
          {/* Phone Lookup Input */}
          <div>
            <label className="block text-xs font-semibold text-slate-300 uppercase tracking-wider mb-1.5">
              Customer Phone Number
            </label>
            <div className="flex gap-2">
              <div className="relative flex-1">
                <input
                  type="text"
                  placeholder="e.g. 0321-9876543 or 03001234567"
                  value={phone}
                  onChange={(e) => setPhone(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleLookup()}
                  className="w-full pl-3 pr-3 py-2.5 bg-slate-950 border border-slate-700 rounded-xl text-white placeholder-slate-500 text-sm focus:outline-none focus:border-amber-500 transition"
                />
              </div>
              <button
                onClick={handleLookup}
                disabled={isSearching}
                className="px-4 py-2.5 rounded-xl bg-amber-500 hover:bg-amber-400 text-slate-950 font-bold text-xs flex items-center gap-1.5 transition"
              >
                <Search className="w-4 h-4" />
                <span>Lookup</span>
              </button>
            </div>
          </div>

          {/* Past Customer History Found Badge */}
          {lookupResult?.found && (
            <div className="p-3.5 rounded-xl bg-teal-950/40 border border-teal-800/60 text-teal-300 text-xs space-y-2">
              <div className="flex items-center justify-between font-bold">
                <div className="flex items-center gap-1.5 text-teal-400">
                  <Check className="w-4 h-4" />
                  <span>Existing Customer Found</span>
                </div>
                <span className="text-[11px] px-2 py-0.5 rounded bg-teal-900/60 border border-teal-700">
                  {lookupResult.totalPastOrders} Past Orders
                </span>
              </div>
              {lookupResult.favoriteItems?.length > 0 && (
                <div className="text-[11px] text-slate-300">
                  <span className="text-slate-400">Favorites: </span>
                  {lookupResult.favoriteItems.join(', ')}
                </div>
              )}
            </div>
          )}

          {/* Customer Details Form */}
          <div className="grid grid-cols-1 gap-3">
            <div>
              <label className="block text-xs font-medium text-slate-400 mb-1 flex items-center gap-1">
                <User className="w-3.5 h-3.5 text-slate-400" /> Customer Name
              </label>
              <input
                type="text"
                placeholder="Customer Name"
                value={customerName}
                onChange={(e) => setCustomerName(e.target.value)}
                className="w-full px-3 py-2 bg-slate-950 border border-slate-700 rounded-lg text-white text-sm focus:outline-none focus:border-teal-500"
              />
            </div>

            <div>
              <label className="block text-xs font-medium text-slate-400 mb-1 flex items-center gap-1">
                <MapPin className="w-3.5 h-3.5 text-slate-400" /> Delivery Address & Landmark
              </label>
              <textarea
                rows={2}
                placeholder="House / Flat #, Street, Sector / Area, City"
                value={address}
                onChange={(e) => setAddress(e.target.value)}
                className="w-full px-3 py-2 bg-slate-950 border border-slate-700 rounded-lg text-white text-sm focus:outline-none focus:border-teal-500"
              />
            </div>

            <div className="p-2.5 rounded-lg bg-slate-800/50 border border-slate-700 text-xs text-slate-400 flex items-center justify-between">
              <span>Fulfillment Branch:</span>
              <span className="font-bold text-teal-400">{selectedBranch?.name || 'Main Branch'}</span>
            </div>
          </div>
        </div>

        <div className="p-4 bg-slate-800 border-t border-slate-700 flex items-center justify-end gap-2">
          <button
            onClick={onClose}
            className="px-4 py-2 rounded-xl bg-slate-700 hover:bg-slate-600 text-slate-200 text-xs font-semibold"
          >
            Cancel
          </button>
          <button
            onClick={handleStartOrder}
            className="flex items-center gap-1.5 px-5 py-2 rounded-xl bg-amber-500 hover:bg-amber-400 text-slate-950 text-xs font-bold shadow-lg shadow-amber-500/20"
          >
            <span>Proceed to Menu Cart</span>
            <ArrowRight className="w-4 h-4" />
          </button>
        </div>
      </div>
    </div>
  );
};

