import React, { useState, useEffect } from 'react';
import {
  Shield,
  Users,
  RefreshCw,
  Save,
  CheckCircle2,
  AlertTriangle,
  ChevronDown,
  Eye,
  Edit3,
  Trash2,
  Download
} from 'lucide-react';
import { posApi } from '../services/api';

interface ModuleDef {
  key: string;
  label: string;
  subModules: { key: string; label: string }[];
}

interface PermissionEntry {
  moduleKey: string;
  subModuleKey: string;
  canView: boolean;
  canEdit: boolean;
  canDelete: boolean;
  canExport: boolean;
}

interface UserOption {
  id: string;
  fullName: string;
  username: string;
  role: number;
}

/**
 * Module keys enforced by the backend permission layer. The empty-string
 * sub-module is the MODULE-LEVEL grant — that is the row `hasModuleAccess` (and
 * the server's ModuleBaseline) reads, so it must always be offered first.
 */
const WHOLE_MODULE_KEY = '';

const DEFAULT_MODULES: ModuleDef[] = [
  { key: 'pos', label: 'POS Terminal', subModules: [{ key: 'billing', label: 'Billing & Checkout' }, { key: 'order_management', label: 'Order Management' }] },
  { key: 'kitchen', label: 'Kitchen Display', subModules: [{ key: 'kds', label: 'Kitchen Display System' }] },
  { key: 'delivery', label: 'Delivery Board', subModules: [{ key: 'dispatch', label: 'Dispatch & Riders' }, { key: 'cod', label: 'COD Settlement' }] },
  { key: 'menu', label: 'Menu, Catalog & Pricing', subModules: [{ key: 'catalog', label: 'Menu & Categories' }, { key: 'pricing', label: 'Item Prices' }, { key: 'tax', label: 'Tax Configuration' }, { key: 'floors', label: 'Floor & Tables' }] },
  { key: 'inventory', label: 'Inventory & Stock', subModules: [{ key: 'ingredients', label: 'Raw Ingredients' }, { key: 'finished', label: 'Finished Stock' }, { key: 'recipes', label: 'Recipes & BOM' }, { key: 'requests', label: 'Stock Requests' }] },
  { key: 'reports', label: 'Reports & Analytics', subModules: [{ key: 'financial', label: 'Financial Reports' }, { key: 'sales', label: 'Sales Analytics' }, { key: 'tax', label: 'Tax Audit' }] },
  { key: 'accounts', label: 'Accounts & Settings', subModules: [{ key: 'settings', label: 'System Settings' }, { key: 'taxrates', label: 'Tax Jurisdictions' }, { key: 'cashflow', label: 'Cash & Shifts' }] },
  { key: 'supplychain', label: 'Supply Chain', subModules: [{ key: 'transfers', label: 'Inter-Branch Transfers' }, { key: 'procurement', label: 'Vendor Procurement' }] },
  { key: 'users', label: 'Staff & Permissions', subModules: [{ key: 'staff', label: 'Staff Accounts' }, { key: 'permissions', label: 'Module Permissions' }] },
  { key: 'admin', label: 'Platform Admin', subModules: [{ key: 'tenants', label: 'Tenant Management' }, { key: 'packages', label: 'Packages & Pricing' }, { key: 'whatsapp', label: 'WhatsApp Config' }] },
];

export const ModulePermissions: React.FC = () => {
  const [modules, setModules] = useState<ModuleDef[]>([]);
  const [users, setUsers] = useState<UserOption[]>([]);
  const [selectedUserId, setSelectedUserId] = useState('');
  const [permissions, setPermissions] = useState<PermissionEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null);

  const loadData = async () => {
    setLoading(true);
    try {
      const [modulesData, usersData] = await Promise.all([
        posApi.getModuleCatalog().catch(() => []),
        posApi.getAdminTenants().catch(() => [])
      ]);
      setModules(Array.isArray(modulesData) && modulesData.length > 0 ? modulesData : DEFAULT_MODULES);

      const tenants = Array.isArray(usersData) ? usersData : [];
      const flatUsers: UserOption[] = [];
      for (const t of tenants) {
        try {
          const tenantUsers = await posApi.getUsers(t.id);
          if (Array.isArray(tenantUsers)) {
            flatUsers.push(...tenantUsers.map((u: any) => ({ id: u.id, fullName: u.fullName, username: u.username, role: u.role })));
          }
        } catch { /* skip */ }
      }
      setUsers(flatUsers);
    } catch (err) {
      console.error('Failed to load permissions data:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { loadData(); }, []);

  const loadUserPermissions = async (userId: string) => {
    setSelectedUserId(userId);
    setMessage(null);
    try {
      const data = await posApi.getUserPermissions(userId);
      if (Array.isArray(data)) {
        setPermissions(data);
      } else {
        setPermissions([]);
      }
    } catch {
      setPermissions([]);
    }
  };

  const getPermission = (moduleKey: string, subModuleKey: string, field: keyof PermissionEntry): boolean => {
    const entry = permissions.find(p => p.moduleKey === moduleKey && p.subModuleKey === subModuleKey);
    return entry ? (entry[field] as boolean) : false;
  };

  const setPermission = (moduleKey: string, subModuleKey: string, field: keyof PermissionEntry, value: boolean) => {
    setPermissions(prev => {
      const existing = prev.find(p => p.moduleKey === moduleKey && p.subModuleKey === subModuleKey);
      if (existing) {
        return prev.map(p =>
          p.moduleKey === moduleKey && p.subModuleKey === subModuleKey
            ? { ...p, [field]: value }
            : p
        );
      }
      return [...prev, {
        moduleKey, subModuleKey,
        canView: field === 'canView' ? value : false,
        canEdit: field === 'canEdit' ? value : false,
        canDelete: field === 'canDelete' ? value : false,
        canExport: field === 'canExport' ? value : false,
      }];
    });
  };

  const handleSave = async () => {
    if (!selectedUserId) return;
    setSaving(true);
    setMessage(null);
    try {
      await posApi.updateUserPermissions(selectedUserId, permissions);
      setMessage({ type: 'success', text: 'Permissions saved successfully' });
    } catch (err) {
      setMessage({ type: 'error', text: 'Failed to save permissions' });
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="text-center">
          <RefreshCw className="w-8 h-8 text-teal-500 animate-spin mx-auto mb-3" />
          <p className="text-sm text-slate-500">Loading permissions data...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 p-4 lg:p-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-teal-500/10 flex items-center justify-center">
            <Shield className="w-5 h-5 text-teal-500" />
          </div>
          <div>
            <h1 className="text-lg font-bold text-slate-900">Module Permissions</h1>
            <p className="text-xs text-slate-500">
              Control what each staff member can access. The <strong>Whole Module</strong> row is what
              gates the sidebar and screens; sub-modules refine it.
            </p>
          </div>
        </div>
        <button
          onClick={handleSave}
          disabled={!selectedUserId || saving}
          className="flex items-center gap-2 px-5 py-2.5 rounded-xl bg-teal-500 hover:bg-teal-600 text-white text-xs font-bold transition disabled:opacity-50"
        >
          <Save className="w-4 h-4" />
          {saving ? 'Saving...' : 'Save Permissions'}
        </button>
      </div>

      {message && (
        <div className={`flex items-center gap-2 px-4 py-3 rounded-xl text-xs font-semibold ${
          message.type === 'success' ? 'bg-teal-50 text-teal-700 border border-teal-200' : 'bg-rose-50 text-rose-700 border border-rose-200'
        }`}>
          {message.type === 'success' ? <CheckCircle2 className="w-4 h-4" /> : <AlertTriangle className="w-4 h-4" />}
          {message.text}
        </div>
      )}

      {/* User Selector */}
      <div className="p-5 rounded-2xl bg-white border border-slate-200">
        <label className="flex items-center gap-2 text-[10px] font-semibold text-slate-500 uppercase mb-2">
          <Users className="w-3.5 h-3.5" /> Select Staff Member
        </label>
        <div className="relative">
          <select
            value={selectedUserId}
            onChange={(e) => loadUserPermissions(e.target.value)}
            className="w-full appearance-none pl-3 pr-8 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs text-slate-900 focus:border-teal-500 focus:ring-2 focus:ring-teal-500/20 cursor-pointer"
          >
            <option value="">-- Choose a user --</option>
            {users.map(u => (
              <option key={u.id} value={u.id}>{u.fullName} ({u.username})</option>
            ))}
          </select>
          <ChevronDown className="absolute right-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-slate-400 pointer-events-none" />
        </div>
      </div>

      {/* Permissions Tree */}
      {selectedUserId && (
        <div className="space-y-4">
          {modules.map((mod) => (
            <div key={mod.key} className="rounded-2xl bg-white border border-slate-200 overflow-hidden">
              <div className="px-5 py-3 bg-slate-50 border-b border-slate-200">
                <h3 className="text-xs font-bold text-slate-900">{mod.label}</h3>
              </div>
              <div className="divide-y divide-slate-100">
                {[{ key: WHOLE_MODULE_KEY, label: 'Whole Module (grants access)' }, ...mod.subModules].map((sub) => (
                  <div
                    key={sub.key || '__module__'}
                    className={`px-5 py-3 flex items-center gap-4 ${sub.key === WHOLE_MODULE_KEY ? 'bg-teal-50/40' : ''}`}
                  >
                    <span className={`text-[11px] font-medium min-w-[140px] ${
                      sub.key === WHOLE_MODULE_KEY ? 'text-teal-800 font-bold' : 'text-slate-700'
                    }`}>
                      {sub.label}
                    </span>
                    <div className="flex items-center gap-3 flex-1">
                      {[
                        { field: 'canView' as const, icon: Eye, label: 'View' },
                        { field: 'canEdit' as const, icon: Edit3, label: 'Edit' },
                        { field: 'canDelete' as const, icon: Trash2, label: 'Delete' },
                        { field: 'canExport' as const, icon: Download, label: 'Export' },
                      ].map(({ field, icon: Icon, label }) => {
                        const hasAccess = getPermission(mod.key, sub.key, field);
                        return (
                          <button
                            key={field}
                            onClick={() => setPermission(mod.key, sub.key, field, !hasAccess)}
                            className={`flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg text-[10px] font-bold transition border ${
                              hasAccess
                                ? 'bg-teal-50 text-teal-700 border-teal-200'
                                : 'bg-rose-50 text-rose-600 border-rose-200'
                            }`}
                          >
                            <Icon className="w-3 h-3" />
                            {label}
                          </button>
                        );
                      })}
                    </div>
                    <div className="shrink-0">
                      {(() => {
                        const allTrue = ['canView', 'canEdit', 'canDelete', 'canExport'].every(
                          f => getPermission(mod.key, sub.key, f as keyof PermissionEntry)
                        );
                        return allTrue ? (
                          <span className="text-[9px] font-bold text-teal-700 bg-teal-50 px-2 py-0.5 rounded-full border border-teal-200">Full Access</span>
                        ) : null;
                      })()}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

