          ))}
        </div>
      </div>

      {/* Right Waiter Ticket Panel */}
      <div className="w-full md:w-80 flex flex-col bg-white border-l border-slate-200">
        <div className="p-3 bg-slate-50 border-b border-slate-200 flex items-center justify-between">
