                    </div>
                  ))
                )}
              </div>

              {/* Info Box */}
              <div className="p-3.5 rounded-xl bg-slate-50 border border-slate-200 text-[11px] space-y-1.5">
                <div className="font-bold text-slate-900">How Device Registration Works</div>
