/**
 * Re-point this device at a different server (e.g. a branch pairing to its Head Office).
 * Persists the choice and updates the live client in one step, so the very next call —
 * including the activation request itself — goes to the new address.
 */
export function setApiBaseUrl(url: string) {
  const trimmed = url.trim().replace(/\/+$/, '');
  if (!trimmed) return;
  try {
    localStorage.setItem('cashly_api_url', trimmed);
  } catch { /* storage blocked — the in-memory re-point still applies for this session */ }
  api.defaults.baseURL = trimmed;
}

// JWT Auth interceptor
api.interceptors.request.use((config) => {
  const token = authStorage.getItem('cashly_pos_token');
  if (token && token !== OFFLINE_SESSION_TOKEN) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

/** A report's location: every location of the business, as head office reads it. */
export const ALL_LOCATIONS = 'all';
const reportLocation = (branchId: string) =>
  branchId === ALL_LOCATIONS ? { allLocations: true } : { branchId };

/**
 * Endpoints the backend leaves open (no bearer token required). A 401 from any
 * of these is a credential/setup problem, not an expired session, so it must NOT
 * tear down the current session.
 */
const PUBLIC_ENDPOINTS = [
  '/api/auth/login',
  '/api/auth/pin-login',
  '/api/auth/email-login',
  '/api/auth/2fa/verify',
  '/api/auth/forgot-password',
  '/api/auth/reset-password',
  '/api/auth/confirm-email',
  '/api/auth/signup',
  '/api/auth/super-admin-login',
  '/api/auth/platform-login',
  '/api/auth/refresh',
  '/api/auth/redeem-invite',
  '/api/setup/status',
  '/api/setup/initialize',
  // Device activation: a brand-new terminal has no session yet, so a 401 here means a bad
  // pairing code, not an expired login, and must not tear the current session down.
  '/api/devices/activate',
  '/api/terminals/heartbeat',
  '/api/public/'
];

function isPublicEndpoint(url?: string): boolean {
  if (!url) return false;
  return PUBLIC_ENDPOINTS.some(p => url.startsWith(p));
}

/** Pull the server's message off an axios rejection, falling back to `fallback`. */
export function getApiErrorMessage(err: unknown, fallback: string): string {
  const data = (err as { response?: { data?: { message?: string; error?: string } } })?.response?.data;
  return data?.message || data?.error || fallback;
}

/** HTTP status of an axios rejection, when there is one. */
export function getApiErrorStatus(err: unknown): number | undefined {
  return (err as { response?: { status?: number } })?.response?.status;
}

/**
 * True when the server refused because the account's plan (or an add-on) does not include the
 * thing being asked for, rather than because the user lacks permission or the record is missing.
 * The filters answer this in the body (`upgradeRequired`), not by status code — the feature filter
 * says 403 and the module/limit filters say 402, so clients cannot key off the number.
 */
export function isUpgradeRequired(err: unknown): boolean {
  const data = (err as { response?: { data?: { upgradeRequired?: boolean } } })?.response?.data;
  return data?.upgradeRequired === true;
}

/**
 * Session teardown + router-aware redirect for expired tokens.
 *
 * `api.ts` is imported BY the store, so it cannot import the store back without
 * a cycle. Instead App.tsx registers a handler at mount that calls
 * `posStore.logout()` and navigates back to the login gate.
 */
type UnauthorizedHandler = () => void;
let onUnauthorized: UnauthorizedHandler | null = null;

export function registerAuthRedirect(fn: UnauthorizedHandler | null) {
  onUnauthorized = fn;
}

/** Keeps a fresh sign-in where the request interceptor and the refresh logic look for it. */
function storeSession(data: LoginResponse) {
  if (!data.token) return;
  authStorage.setItem('cashly_pos_token', data.token);
  if (data.refreshToken) authStorage.setItem('cashly_pos_refresh_token', data.refreshToken);
  authStorage.setItem('cashly_pos_user', JSON.stringify(data.user));
}

function clearSession() {
  authStorage.removeItem('cashly_pos_token');
  authStorage.removeItem('cashly_pos_refresh_token');
  authStorage.removeItem('cashly_pos_user');
}

// The access token is short-lived (2h) on purpose — this is what keeps a shift-long
// session alive without kicking the cashier back to the PIN screen mid-order. Concurrent
// 401s share one in-flight refresh call instead of each firing their own.
let refreshInFlight: Promise<string | null> | null = null;

async function tryRefreshToken(): Promise<string | null> {
  const storedRefreshToken = authStorage.getItem('cashly_pos_refresh_token');
  if (!storedRefreshToken) return null;
  if (!refreshInFlight) {
    refreshInFlight = api
      .post<LoginResponse>('/api/auth/refresh', { refreshToken: storedRefreshToken })
      .then((res) => {
        if (!res.data.token) return null;
        authStorage.setItem('cashly_pos_token', res.data.token);
        if (res.data.refreshToken) authStorage.setItem('cashly_pos_refresh_token', res.data.refreshToken);
        authStorage.setItem('cashly_pos_user', JSON.stringify(res.data.user));
        return res.data.token;
      })
      .catch(() => null)
      .finally(() => { refreshInFlight = null; });
  }
  return refreshInFlight;
}

api.interceptors.response.use(
  (response) => response,
  async (error) => {
    // Every /api/* endpoint except the public ones above now requires a valid JWT.
    // A 401 therefore means the session is invalid or expired.
    if (error.response?.status === 401 && !isPublicEndpoint(error.config?.url)) {
      // Only act when a token was actually sent. A 401 on a request that carried no
      // token just means we're not signed in yet (e.g. the setup wizard probing
      // tenants) — tearing down there would eject the user from the installation flow.
      const sentToken = !!error.config?.headers?.Authorization;
      if (sentToken && !error.config?._retriedAfterRefresh) {
        const newToken = await tryRefreshToken();
        if (newToken) {
          error.config._retriedAfterRefresh = true;
          error.config.headers.Authorization = `Bearer ${newToken}`;
          return api.request(error.config);
        }
      }
      if (sentToken) {
        // Refresh failed too (or there was nothing to refresh) — the session is
        // genuinely over. Clear the raw keys first so the request interceptor stops
        // sending a dead token even if the handler below is not registered yet.
        clearSession();
        try {
          onUnauthorized?.();
        } catch {
          // best-effort; the login gate renders as soon as the store clears
        }
      }
    }

    // 402 is the billing ladder, not an auth failure: the session is perfectly valid, the
    // ACCOUNT is in arrears. Signing the user out here would be exactly wrong — they need to
    // stay in the app to see the message and pay. Surfaced to the shell instead.
    if (error.response?.status === 402 && error.response?.data?.billingAction) {
      try {
        onBillingRestricted?.(error.response.data.tenantStatus, error.response.data.message);
      } catch {
        // best-effort
      }
    }

    return Promise.reject(error);
  }
);

/**
 * Registered by App.tsx so a 402 can raise the billing banner without api.ts importing
 * the store (which imports api.ts — same cycle the 401 handler avoids).
 */
let onBillingRestricted: ((status: string, message: string) => void) | null = null;
export function registerBillingHandler(handler: (status: string, message: string) => void) {
  onBillingRestricted = handler;
}

